-- Entasis Academy, migration 9 : schemas et figures des decks (brouillons).
--
-- Genere par scripts/academy/generer-decks.mjs depuis scripts/academy/decks/*.json :
-- ne pas editer a la main, regenerer. Complete le brouillon courant d un
-- module deja seme par la migration 7 : pose les schemas de la version
-- (remplacement par cle, les autres cles conservees), pose payload.figure
-- sur les exercices existants reperes par (ordre, type) qui n en ont pas
-- encore, insere les exercices nouveaux (ordre au dela du maximum existant)
-- avec leur corrige, ordre et association deja melanges. Idempotent. Une
-- version publiee n est jamais touchee : sans brouillon, raise notice et
-- rien. A appliquer apres la migration 8 (colonne academy_module_versions.schemas).

-- ── Schemas : PER et préparation de la retraite (per-et-retraite) ──
do $schemas_per_et_retraite$
declare v_mod uuid; v_ver uuid; v_max integer; v_item uuid; v_nouveaux jsonb; v_conserves jsonb;
begin
  select id into v_mod from public.academy_modules where slug = $academy_deck$per-et-retraite$academy_deck$;
  if v_mod is null then
    raise notice 'academy_9_schemas : module % absent, rien a faire (semer la migration 7 d abord)', $academy_deck$per-et-retraite$academy_deck$;
    return;
  end if;
  select id into v_ver from public.academy_module_versions where module_id = v_mod and statut = 'brouillon' order by numero desc limit 1;
  if v_ver is null then
    raise notice 'academy_9_schemas : aucun brouillon pour %, rien a faire (une version publiee ne se modifie pas)', $academy_deck$per-et-retraite$academy_deck$;
    return;
  end if;
  -- Schemas de la version : les cles du deck remplacent les leurs, les autres restent.
  v_nouveaux := $academy_deck$[{"cle":"vie_versement","titre":"La vie d’un versement PER","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>La vie d’un versement PER</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"36\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"600\" fill=\"#162443\">La vie d’un versement PER</text><rect x=\"16\" y=\"66\" width=\"176\" height=\"192\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><rect x=\"232\" y=\"66\" width=\"176\" height=\"192\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><rect x=\"448\" y=\"66\" width=\"176\" height=\"192\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><circle cx=\"40\" cy=\"66\" r=\"15\" fill=\"#C5A55A\"/><circle cx=\"256\" cy=\"66\" r=\"15\" fill=\"#C5A55A\"/><circle cx=\"472\" cy=\"66\" r=\"15\" fill=\"#C5A55A\"/><text x=\"40\" y=\"71\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">1</text><text x=\"256\" y=\"71\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">2</text><text x=\"472\" y=\"71\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#FFFFFF\">3</text><text x=\"104\" y=\"102\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"600\" fill=\"#162443\">À l’entrée</text><text x=\"320\" y=\"102\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"600\" fill=\"#162443\">Pendant</text><text x=\"536\" y=\"102\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"600\" fill=\"#162443\">À la sortie</text><line x1=\"40\" y1=\"114\" x2=\"168\" y2=\"114\" stroke=\"#8A95A8\" stroke-width=\"2\"/><line x1=\"256\" y1=\"114\" x2=\"384\" y2=\"114\" stroke=\"#8A95A8\" stroke-width=\"2\"/><line x1=\"472\" y1=\"114\" x2=\"600\" y2=\"114\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"104\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Versement volontaire</text><text x=\"104\" y=\"162\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">déduit du revenu</text><text x=\"104\" y=\"184\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">imposable, dans la</text><text x=\"104\" y=\"206\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">limite du plafond</text><text x=\"104\" y=\"232\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Avant 70 ans</text><text x=\"104\" y=\"249\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Renonciation sur option</text><text x=\"320\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Sommes bloquées</text><text x=\"320\" y=\"162\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">jusqu’à la retraite</text><text x=\"320\" y=\"184\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">sauf cas prévus</text><text x=\"320\" y=\"206\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">par la loi</text><text x=\"320\" y=\"232\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Gestion pilotée</text><text x=\"320\" y=\"249\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">par défaut</text><text x=\"536\" y=\"140\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Capital imposé</text><text x=\"536\" y=\"162\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">au barème progressif</text><text x=\"536\" y=\"184\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Rente imposée</text><text x=\"536\" y=\"206\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">comme une pension</text><text x=\"536\" y=\"232\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Non déduit :</text><text x=\"536\" y=\"249\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">capital exonéré</text><line x1=\"194\" y1=\"162\" x2=\"222\" y2=\"162\" stroke=\"#C5A55A\" stroke-width=\"2\"/><polygon points=\"220,155 232,162 220,169\" fill=\"#C5A55A\"/><line x1=\"410\" y1=\"162\" x2=\"438\" y2=\"162\" stroke=\"#C5A55A\" stroke-width=\"2\"/><polygon points=\"436,155 448,162 436,169\" fill=\"#C5A55A\"/><rect x=\"16\" y=\"282\" width=\"608\" height=\"60\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"320\" y=\"308\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"600\" fill=\"#162443\">Impôt reporté, pas effacé</text><text x=\"320\" y=\"330\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">L’intérêt se mesure entre la tranche actuelle et celle de la retraite.</text></svg>","legende":"Déduit à l’entrée, bloqué jusqu’à la retraite, imposé à la sortie : l’impôt est reporté, pas effacé."},{"cle":"deblocage_anticipe","titre":"Les cas de déblocage anticipé du PER","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 640 360\" font-family=\"system-ui, -apple-system, Segoe UI, sans-serif\"><title>Les cas de déblocage anticipé du PER</title><rect x=\"0\" y=\"0\" width=\"640\" height=\"360\" fill=\"#FFFFFF\"/><text x=\"320\" y=\"36\" text-anchor=\"middle\" font-size=\"20\" font-weight=\"600\" fill=\"#162443\">Les cas de déblocage anticipé du PER</text><rect x=\"16\" y=\"62\" width=\"392\" height=\"224\" rx=\"8\" fill=\"#F5EDD8\" stroke=\"#162443\" stroke-width=\"2\"/><text x=\"212\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"600\" fill=\"#162443\">Sept accidents de la vie</text><line x1=\"32\" y1=\"102\" x2=\"392\" y2=\"102\" stroke=\"#8A95A8\" stroke-width=\"2\"/><circle cx=\"40\" cy=\"120\" r=\"4\" fill=\"#C5A55A\"/><circle cx=\"40\" cy=\"144\" r=\"4\" fill=\"#C5A55A\"/><circle cx=\"40\" cy=\"168\" r=\"4\" fill=\"#C5A55A\"/><circle cx=\"40\" cy=\"192\" r=\"4\" fill=\"#C5A55A\"/><circle cx=\"40\" cy=\"216\" r=\"4\" fill=\"#C5A55A\"/><circle cx=\"40\" cy=\"240\" r=\"4\" fill=\"#C5A55A\"/><circle cx=\"40\" cy=\"264\" r=\"4\" fill=\"#C5A55A\"/><text x=\"52\" y=\"125\" font-size=\"14\" fill=\"#2C3548\">Décès du conjoint ou du partenaire de Pacs</text><text x=\"52\" y=\"149\" font-size=\"14\" fill=\"#2C3548\">Invalidité de 2e ou 3e catégorie</text><text x=\"52\" y=\"173\" font-size=\"14\" fill=\"#2C3548\">Handicap d’un enfant</text><text x=\"52\" y=\"197\" font-size=\"14\" fill=\"#2C3548\">Surendettement</text><text x=\"52\" y=\"221\" font-size=\"14\" fill=\"#2C3548\">Fin des droits au chômage</text><text x=\"52\" y=\"245\" font-size=\"14\" fill=\"#2C3548\">Cessation de mandat social depuis deux ans</text><text x=\"52\" y=\"269\" font-size=\"14\" fill=\"#2C3548\">Liquidation judiciaire d’un non salarié</text><rect x=\"424\" y=\"62\" width=\"200\" height=\"224\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"524\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"600\" fill=\"#162443\">Le seul autre cas</text><line x1=\"440\" y1=\"102\" x2=\"608\" y2=\"102\" stroke=\"#C5A55A\" stroke-width=\"2\"/><text x=\"524\" y=\"132\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">Achat de la</text><text x=\"524\" y=\"152\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"600\" fill=\"#162443\">résidence principale</text><text x=\"524\" y=\"184\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">Versements volontaires</text><text x=\"524\" y=\"202\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">et épargne salariale</text><text x=\"524\" y=\"220\" text-anchor=\"middle\" font-size=\"13\" fill=\"#2C3548\">seulement</text><text x=\"524\" y=\"250\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">Versements obligatoires :</text><text x=\"524\" y=\"268\" text-anchor=\"middle\" font-size=\"13\" fill=\"#8A95A8\">toujours bloqués</text><rect x=\"16\" y=\"300\" width=\"608\" height=\"44\" rx=\"8\" fill=\"#FFFFFF\" stroke=\"#8A95A8\" stroke-width=\"2\"/><text x=\"320\" y=\"319\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">Rien d’autre : un besoin de trésorerie passager ou des travaux</text><text x=\"320\" y=\"337\" text-anchor=\"middle\" font-size=\"14\" fill=\"#2C3548\">n’ouvrent aucun déblocage avant la retraite.</text></svg>","legende":"Sept accidents de la vie et un seul projet, la résidence principale. Tout le reste attend la retraite."}]$academy_deck$::jsonb;
  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_conserves
    from jsonb_array_elements(coalesce((select schemas from public.academy_module_versions where id = v_ver), '[]'::jsonb)) s
   where not exists (select 1 from jsonb_array_elements(v_nouveaux) x where x ->> 'cle' = s ->> 'cle');
  update public.academy_module_versions set schemas = v_conserves || v_nouveaux, updated_at = now() where id = v_ver;
  -- Figures : posee sur l exercice existant (ordre, type) qui n en a pas ; au dela du maximum, exercice nouveau.
  select coalesce(max(ordre), 0) into v_max from public.academy_items where version_id = v_ver;
  if v_max >= 7 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"deblocage_anticipe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 7 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 7, $academy_deck$choix$academy_deck$, $academy_deck$Choix des enveloppes$academy_deck$, 3, $academy_deck${"enonce":"Cas fictif. Monsieur V., prévoyance en place et six mois de dépenses en épargne disponible, veut placer 40 000 euros, dont 25 000 euros destinés à des travaux dans trois ans. Il demande de tout verser sur un PER. Quelle réponse est conforme ?","choix":["Tout sur le PER, la déduction sera maximale cette année","Placer les 25 000 euros du projet sur une enveloppe disponible et une part longue sur le PER dans la limite du plafond, le tout chiffré dans l'étude","Tout sur un livret réglementé, la sécurité prime","Tout en assurance vie, qui remplace le PER"],"figure":{"ref":"deblocage_anticipe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":1}$academy_deck$::jsonb, $academy_deck$Des travaux dans trois ans ne sont pas un cas de déblocage anticipé : chaque enveloppe répond à un objectif de vie distinct.$academy_deck$);
  end if;
  if v_max >= 17 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"deblocage_anticipe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 17 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 17, $academy_deck$multi$academy_deck$, $academy_deck$Blocage et déblocage anticipé$academy_deck$, 1, $academy_deck${"enonce":"Cochez tout ce qui constitue un cas de déblocage anticipé du PER.","choix":["Le surendettement","L'achat de la résidence principale","L'achat d'une résidence secondaire","L'invalidité de deuxième ou troisième catégorie du titulaire","Des travaux dans le local professionnel","Un projet de voyage"],"figure":{"ref":"deblocage_anticipe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,3]}$academy_deck$::jsonb, $academy_deck$Surendettement, invalidité et achat de la résidence principale sont prévus ; travaux, résidence secondaire et voyage ne le sont pas.$academy_deck$);
  end if;
  if v_max >= 18 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"vie_versement"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 18 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 18, $academy_deck$multi$academy_deck$, $academy_deck$Déduction et fiscalité de sortie$academy_deck$, 2, $academy_deck${"enonce":"Cochez tout ce qui est exact au sujet des versements volontaires déduits du revenu imposable.","choix":["Ils sont déductibles par principe s'ils sont effectués avant 70 ans","La part du capital qui leur correspond est exonérée à la sortie","La part du capital qui leur correspond est imposée au barème progressif à la sortie","L'impôt correspondant est définitivement effacé","La rente qui en découle suit les règles des pensions de retraite"],"figure":{"ref":"vie_versement"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,2,4]}$academy_deck$::jsonb, $academy_deck$La déduction reporte l'impôt à la sortie : capital au barème progressif, rente comme une pension de retraite.$academy_deck$);
  end if;
  if v_max >= 24 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"vie_versement"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 24 and type = $academy_deck$ordre$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 24, $academy_deck$ordre$academy_deck$, $academy_deck$Déduction et fiscalité de sortie$academy_deck$, 2, $academy_deck${"enonce":"Remettez dans l'ordre chronologique le parcours fiscal d'un versement volontaire déduit.","elements":["Déduction du revenu imposable dans la limite du plafond","Versement volontaire effectué avant 70 ans","Sortie en capital ou en rente","Blocage des sommes jusqu'à la retraite","Imposition de la part correspondante au barème progressif ou comme une pension"],"figure":{"ref":"vie_versement"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"ordre":[1,0,3,2,4]}$academy_deck$::jsonb, $academy_deck$La déduction à l'entrée reporte l'imposition au moment de la sortie, elle ne l'efface pas.$academy_deck$);
  end if;
  if v_max >= 41 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"vie_versement"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 41 and type = $academy_deck$choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 41, $academy_deck$choix$academy_deck$, $academy_deck$Déduction et fiscalité de sortie$academy_deck$, 1, $academy_deck${"enonce":"Sur le schéma de la vie d’un versement PER, à quelle étape l’impôt sur les sommes déduites se paie réellement ?","choix":["À l’entrée, au moment du versement","Pendant le blocage, chaque année","À la sortie, en capital ou en rente","Jamais, la déduction efface l’impôt"],"figure":{"ref":"vie_versement"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":2}$academy_deck$::jsonb, $academy_deck$La déduction à l’entrée reporte l’impôt à la sortie : capital au barème progressif, rente comme une pension.$academy_deck$);
  end if;
  if v_max >= 42 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"deblocage_anticipe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 42 and type = $academy_deck$multi$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 42, $academy_deck$multi$academy_deck$, $academy_deck$Blocage et déblocage anticipé$academy_deck$, 2, $academy_deck${"enonce":"Sur le schéma des cas de déblocage anticipé, cochez tout ce qui est exact au sujet de la case « Achat de la résidence principale ».","choix":["C’est le seul cas qui n’est pas un accident de la vie","Elle libère les droits issus des versements volontaires","Elle libère les droits issus de l’épargne salariale","Elle libère les droits issus des versements obligatoires","Elle s’étend à l’achat d’une résidence secondaire"],"figure":{"ref":"deblocage_anticipe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"indices":[0,1,2]}$academy_deck$::jsonb, $academy_deck$La résidence principale est le seul projet de vie prévu par la loi ; les droits issus des versements obligatoires restent bloqués.$academy_deck$);
  end if;
  if v_max >= 43 then
    update public.academy_items set payload = payload || jsonb_build_object('figure', $academy_deck${"ref":"deblocage_anticipe"}$academy_deck$::jsonb), updated_at = now()
     where version_id = v_ver and ordre = 43 and type = $academy_deck$trou_choix$academy_deck$ and archive_le is null and not (payload ? 'figure');
  else
    insert into public.academy_items (version_id, ordre, type, competence, difficulte, payload)
    values (v_ver, 43, $academy_deck$trou_choix$academy_deck$, $academy_deck$Blocage et déblocage anticipé$academy_deck$, 2, $academy_deck${"phrase":"Sur le schéma, la bande du bas rappelle que des travaux ou un besoin de trésorerie passager n’ouvrent aucun déblocage : la liste des huit cas est donc ___.","choix":["limitative","indicative","négociable","provisoire"],"figure":{"ref":"deblocage_anticipe"}}$academy_deck$::jsonb)
    returning id into v_item;
    insert into public.academy_items_corriges (item_id, corrige, explication) values (v_item, $academy_deck${"index":0}$academy_deck$::jsonb, $academy_deck$La loi fixe une liste limitative : sept accidents de la vie et l’achat de la résidence principale. Ce qui n’y figure pas attend la retraite.$academy_deck$);
  end if;
end
$schemas_per_et_retraite$;
